module dff_sr (
    input D,
    input CLK,
    input SET_B,
    input RESET_B,
    output reg Q,
    output reg Q_N
);

always @ (posedge CLK) begin
    if (SET_B == 0) begin
        Q <= 1;
        Q_N <= 0;
    end else if (RESET_B == 0) begin
        Q <= 0;
        Q_N <= 1;
    end else begin
        Q <= D;
        Q_N <= ~D;
    end
end

endmodule

testbench:
`timescale 1ns/1ps

module dff_sr_tb;

    // Testbench signals (sequential circuit)
    reg CLK;
    reg D;
    reg RESET_B;
    reg SET_B;
    wire Q;
    wire Q_N;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    dff_sr dut (
        .CLK(CLK),
        .D(D),
        .RESET_B(RESET_B),
        .SET_B(SET_B),
        .Q(Q),
        .Q_N(Q_N)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            D = 0;
            SET_B = 1;
            RESET_B = 0;
            @(posedge CLK);
            #2;
            RESET_B = 1;
            #5;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Test %0d: Asynchronous Reset", test_num);
            reset_dut();

            RESET_B = 0;
            SET_B = 1;
            D = 1;
            #5;
            #1;

            check_outputs(1'b0, 1'b1);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Test %0d: Asynchronous Set", test_num);
            reset_dut();
            RESET_B = 1;
            SET_B = 0;
