            #2;
            D = 0;
            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0, 1'b1);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("Test %0d: Async Reset Priority over Clock/Data", test_num);
            reset_dut();
            RESET_B = 1;
            SET_B = 1;
            D = 1;
            @(posedge CLK);
            #2;
            RESET_B = 0;
            D = 1;
            #5;
            #1;

            check_outputs(1'b0, 1'b1);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            $display("Test %0d: Async Set Priority over Clock/Data", test_num);
            reset_dut();
            RESET_B = 1;
            SET_B = 1;
            D = 0;
            @(posedge CLK);
            #2;
            SET_B = 0;
            D = 0;
            #5;
            #1;

            check_outputs(1'b1, 1'b0);
        end
        endtask

    task testcase007;

        begin
            test_num = 7;
            $display("Test %0d: Negative Clock Edge Stability", test_num);
            reset_dut();
            RESET_B = 1;
            SET_B = 1;
            D = 1;
            @(posedge CLK);
            #2;
            D = 0;
            @(negedge CLK);
            #2;

