module adder_subtractor (
  input [3:0] A,
  input [3:0] B,
  input Cin,
  input Mode,
  output [3:0] Sum,
  output Cout
);

  wire [3:0] Adder_out;
  wire [3:0] Sub_out;
  wire [3:0] Twos_comp;
  wire Mode_inv;

  assign Mode_inv = ~Mode;

  // Adder
  ripple_carry_adder adder (
    .A(A),
    .B(B),
    .Cin(Cin),
    .Sum(Adder_out),
    .Cout(Cout)
  );

  // Subtractor
  assign Twos_comp = ~B + 1;
  ripple_carry_adder subtractor (
    .A(A),
    .B(Twos_comp),
    .Cin(Mode),
    .Sum(Sub_out),
    .Cout()
  );

  // Multiplexer
  assign Sum = Mode_inv ? Adder_out : Sub_out;

endmodule

