module myClockGater(
  input CLK, 
  input EN, 
  input TE, 
  output ENCLK
);

  reg gated_en;

  always @(posedge CLK) begin
    if (EN && TE) begin
      gated_en <= 1'b1;
    end else begin
      gated_en <= 1'b0;
    end
  end

  TLATNTSCAX2TS latch(
    .E(gated_en),
    .SE(TE),
    .CK(CLK),
    .ECK(ENCLK)
  );

endmodule

