module priority_encoder (
    input [3:0] in,
    input enable,
    output reg [1:0] pos
);

always @ (in or enable) begin
    if (enable == 1'b0) begin
        pos <= 2'b0;
    end
    else if (in[3] == 1'b1) begin
        pos <= 2'b11;
    end
    else if (in[2] == 1'b1) begin
        pos <= 2'b10;
    end
    else if (in[1] == 1'b1) begin
        pos <= 2'b01;
    end
    else if (in[0] == 1'b1) begin
        pos <= 2'b00;
    end
    else begin
        pos <= 2'b0;
    end
end

endmodule

