module top_module (
    input in,
    output out
);

    // Instantiate sub-modules
    ent_ba inst_ba();
    ent_bb inst_bb();

    // Wire up sub-modules to top-level ports
    assign inst_ba.in = in;
    assign inst_bb.in = inst_ba.out;
    assign out = inst_bb.out;

endmodule

module t (
   // Inputs
   input clk
   );

   reg prev_clk;
   reg [31:0] counter;

   always @(posedge clk) begin
      if (prev_clk == 1'b0 && clk == 1'b1) begin
         counter <= counter + 1;
      end
      prev_clk <= clk;
   end

   wire  a = clk;
   wire  b = 1'b0;

   array_test array_test_i (
      // Inputs
      .clk(clk),
      .counter(counter)
   );

endmodule

