module shift_register(load, shift, data_in, data_out);
    input load, shift;
    input [3:0] data_in;
    output [3:0] data_out;

    reg [3:0] shift_reg;

    always @(*) begin
        if (load)
            shift_reg <= data_in;
        else if (shift)
            shift_reg <= {shift_reg[2:0], 1'b0};
    end

    assign data_out = shift_reg;
endmodule

module Multiplexer_AC__parameterized68
   (ctrl,
    D0,
    D1,
    S);
  input ctrl;
  input [0:0]D0;
  input [0:0]D1;
  output [0:0]S;

  wire [0:0]D0_wire;
  wire [0:0]D1_wire;
  wire [0:0]S_wire;
  wire ctrl_wire;

  assign D0_wire = D0;
  assign D1_wire = D1;
  assign ctrl_wire = ctrl;

  LUT3 #(
    .INIT(8'hB8)) 
    \S[0]_INST_0 
       (.I0(D1_wire),
        .I1(ctrl_wire),
        .I2(D0_wire),
        .O(S_wire));

  assign S = S_wire;
endmodule

module shift_register (
    input wire clk,
    input wire [3:0] inp,
    output wire [15:0] arr_out
);

    logic [15:0] arr;

    always @(posedge clk) begin
        arr[15:1] <= arr[14:0];
        arr[0] <= inp[0];
    end

    always @(posedge clk) begin
        arr[15:1] <= arr[14:0];
        arr[0] <= inp[1];
    end

    always @(posedge clk) begin
        arr[15:1] <= arr[14:0];
        arr[0] <= inp[2];
    end

    always @(posedge clk) begin
        arr[15:1] <= arr[14:0];
        arr[0] <= inp[3];
    end

    assign arr_out = arr;

endmodule

module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg ENCLK;

  always @ (posedge CLK) begin
    if (EN && TE) begin
      ENCLK <= 1'b1;
    end else begin
      ENCLK <= 1'b0;
    end
  end

endmodule

