module dual_edge_ff (
    input clk,
    input reset,
    input d,
    output reg q
);

reg q1, q2;

always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        q1 <= 0;
        q2 <= 0;
    end else begin
        q1 <= d;
        q2 <= q1;
    end
end

always @(negedge clk or negedge reset) begin
    if (reset == 0) begin
        q <= 0;
    end else begin
        q <= q2;
    end
end

endmodule

module nand2_en (
    output Z,
    input A,
    input B,
    input EN
);

    wire nand1_out;
    wire nand2_out;
    wire and_out;

    // Implement NAND1 gate
    assign nand1_out = ~(A & B);

    // Implement NAND2 gate
    assign nand2_out = ~(nand1_out & EN);

    // Implement AND gate
    assign and_out = A & B;

    // Implement final output
    assign Z = nand2_out & and_out;

endmodule

