module two_bit_sat_counter (
    input [1:0] count_i,
    input op,
    output [1:0] count
);

    always @*
    begin
        case (count_i)
            2'b00: count = op ? 2'b01 : 2'b00;
            2'b01: count = op ? 2'b10 : 2'b00;
            2'b10: count = op ? 2'b10 : 2'b01;
            2'b11: count = op ? 2'b11 : 2'b10;
        endcase
    end

endmodule

module voltage_level_shifter (
    VPWR,
    VGND,
    VPB,
    VNB,
    VPB_OUT,
    VNB_OUT,
    VPWR_OUT,
    VGND_OUT
);

    input VPWR;
    input VGND;
    input VPB;
    input VNB;
    output VPB_OUT;
    output VNB_OUT;
    output VPWR_OUT;
    output VGND_OUT;

    assign VPWR_OUT = VPWR;
    assign VGND_OUT = VGND;

    assign VPB_OUT = (VPB == 1'b1) ? VPWR : VGND;
    assign VNB_OUT = (VNB == 1'b1) ? VPWR : VGND;

endmodule

module xor_multiplexer_4bit (
    input [3:0] a,
    input [3:0] b,
    input sel,
    output reg [3:0] out
);

    always @(*) begin
        out[0] = a[0] ^ (sel & b[0]);
        out[1] = a[1] ^ (sel & b[1]);
        out[2] = a[2] ^ (sel & b[2]);
        out[3] = a[3] ^ (sel & b[3]);
    end

endmodule

module mux4_8bit #(parameter WIDTH = 8)
             (input      [WIDTH-1:0] d0, d1, d2, d3,
              input      [1:0]       sel, 
              output reg [WIDTH-1:0] y);

   always @(*)
      case(sel)
         2'b00: y = d0;
         2'b01: y = d1;
         2'b10: y = d2;
         2'b11: y = d3;
      endcase
endmodule

